def possibleBipartition(n: int, dislikes: list[list[int]]) -> bool:
    from collections import defaultdict, deque
    adj = defaultdict(list)
    for u, v in dislikes:
        adj[u].append(v)
        adj[v].append(u)
    color = {}
    for i in range(1, n + 1):
        if i not in color:
            color[i] = 0
            q = deque([i])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if v not in color:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

